import { useEffect, useState } from "react";

function Marks() {
  const [students, setStudents] = useState([]);
  const [marks, setMarks] = useState({}); // { studentId: {subject: marks} }
  const [subject, setSubject] = useState("");
  const [totalMarks, setTotalMarks] = useState("");
  const [subjectsList, setSubjectsList] = useState([]); // [{name, total}]

  useEffect(() => {
    setStudents(JSON.parse(localStorage.getItem("students")) || []);

    // Load existing subjects
    const existingSubjects = JSON.parse(localStorage.getItem("subjects")) || [];
    setSubjectsList(existingSubjects);

    // Load existing marks
    const existingMarks = JSON.parse(localStorage.getItem("marks")) || {};
    setMarks(existingMarks);
  }, []);

  // Add subject dynamically without overwriting previous ones
  const addSubject = () => {
    if (subject && totalMarks && !subjectsList.find(s => s.name === subject)) {
      const newSubjects = [...subjectsList, { name: subject, total: Number(totalMarks) }];
      setSubjectsList(newSubjects);
      localStorage.setItem("subjects", JSON.stringify(newSubjects)); // Save subjects
      setSubject("");
      setTotalMarks("");
    }
  };

  // Handle marks input for each student
  const handleMarksChange = (studentId, subj, value) => {
    const newMarks = {
      ...marks,
      [studentId]: {
        ...marks[studentId],
        [subj]: Number(value)
      }
    };
    setMarks(newMarks);
  };

  // Save marks to LocalStorage (merge with previous)
  const saveMarks = () => {
    const storedMarks = JSON.parse(localStorage.getItem("marks")) || {};

    students.forEach(student => {
      storedMarks[student.id] = {
        ...storedMarks[student.id],
        ...marks[student.id]
      };
    });

    localStorage.setItem("marks", JSON.stringify(storedMarks));
    alert("Marks saved successfully!");
  };

  return (
    <div style={{ padding: "20px" }}>
      <h2>Enter Student Marks</h2>

      <div style={{ marginBottom: "20px" }}>
        <input
          placeholder="Enter subject"
          value={subject}
          onChange={e => setSubject(e.target.value)}
        />
        <input
          placeholder="Total marks"
          type="number"
          value={totalMarks}
          onChange={e => setTotalMarks(e.target.value)}
          style={{ marginLeft: "10px" }}
        />
        <button onClick={addSubject} style={{ marginLeft: "10px" }}>Add Subject</button>
      </div>

      {subjectsList.length === 0 && <p>No subjects added</p>}

      {students.map(student => (
        <div key={student.id} style={{ border: "1px solid #ccc", padding: "10px", marginBottom: "10px" }}>
          <b>{student.name}</b> (Roll: {student.roll})
          <br /><br />

          {subjectsList.map(subj => (
            <div key={subj.name} style={{ marginBottom: "5px" }}>
              <label>{subj.name} (Max: {subj.total}): </label>
              <input
                type="number"
                max={subj.total}
                placeholder="Marks obtained"
                value={(marks[student.id] && marks[student.id][subj.name]) || ""}
                onChange={e => handleMarksChange(student.id, subj.name, e.target.value)}
              />
            </div>
          ))}
        </div>
      ))}

      <button onClick={saveMarks}>Save All Marks</button>
    </div>
  );
}

export default Marks;
